from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Count_rtpm_files(EmssimCommand):
    def __init__(self, method="!ls UPLOADS/KEYSTATS/RTPM/ | wc -l", timeout=60, rpc_connection_name='localRPC'):
        super(Count_rtpm_files, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Count_rtpm_files, self).on_new_data(**data)
        if 'msg' in data:
            self._ret['msg'] = data['msg']
